  "data": { "supported": ["2026-07-28", "2025-11-25"], "requested": "1900-01-01" } } }
</code></pre> <pre><code>{ "jsonrpc": "2.0", "id": 1, "error": { "code": -32020,
  "message": "Header mismatch: Mcp-Name header value 'foo' does not match body value 'bar'" } }
</code></pre>
